const body = $input.first().json;

const event = body.event ?? 'unknown';
const email = body.email ?? '(no email)';
const platform = body.platform ?? '(no platform)';
const ts = new Date().toISOString();

// Treat anything not explicitly 'success' as a failure signal
const isSuccess = body.status === 'success';

return [{ json: { event, email, platform, ts, isSuccess, raw: body } }];

const d = $input.first().json;
console.log(`[vibe-monitor] OK  event=${d.event} platform=${d.platform} ts=${d.ts}`);
return [{ json: { logged: true, ...d } }];

const d = $input.first().json;
console.error(`[vibe-monitor] FAIL event=${d.event} platform=${d.platform} ts=${d.ts}`);
return [{ json: { logged: true, ...d } }];

